contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount) public payable {
        require(address(this).balance >= amount);
        c.deposit{value: amount}();
        uint cBefore = address(c).balance;
        uint myBefore = address(this).balance;
        bool reverted;
        try c.withdrawAll() { reverted = false; } catch { reverted = true; }
        if (reverted) {
            assert(address(c).balance == cBefore && address(this).balance == myBefore);
        } else {
            assert(
                cBefore >= amount &&
                cBefore - address(c).balance == amount &&
                address(this).balance >= myBefore &&
                address(this).balance - myBefore == amount
            );
        }
    }
    receive() external payable {}
}

