contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint a, uint b) public payable {
        require(address(this).balance >= a + b);
        uint cb0 = address(c).balance;
        uint tb0 = address(this).balance;
        c.deposit{value: a}();
        c.withdrawAll();
        uint tb1 = address(this).balance;
        c.deposit{value: b}();
        c.withdrawAll();
