contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount) public payable {
        require(address(this).balance >= amount);
        uint beforeSelf = address(this).balance;
        c.deposit{value: amount}();
        uint beforeZero = address(this).balance;
        // zero-value deposit must not revert
        c.deposit();
        assert(address(c).balance == beforeZero);
        // withdrawAll returns exactly the deposited amount, not more
        c.withdrawAll();
        assert(address(this).balance == beforeSelf);
        // further withdrawAll transfers nothing further (credit was zeroed)
        uint mid = address(this).balance;
        c.withdrawAll();
        assert(address(this).balance == mid && address(c).balance == address(c).balance);
    }
    receive() external payable {}
}

